-- Toledo+ API (Cloudflare D1) — schema.
-- Apply:  npx wrangler d1 execute toledo-plus --remote --file=worker/schema.sql
-- Privacy: no names, e-mails (except `feedback.contact`, typed by the user), student numbers or Toledo data.
-- No IP addresses: rate-limit keys use a SHA-256 of (IP + day + secret salt) and are deleted after 2 days.

-- One row per anonymous install id (random UUID v4 generated by the extension; deleted locally on opt-out,
-- and here via POST /v1/forget).
CREATE TABLE IF NOT EXISTS installs (
  id          TEXT PRIMARY KEY,           -- uuid v4
  first_seen  INTEGER NOT NULL,           -- ms epoch
  last_seen   INTEGER NOT NULL,           -- ms epoch
  version     TEXT NOT NULL,              -- extension version, e.g. 1.2.0
  browser     TEXT NOT NULL,              -- chrome | edge | brave | opera | other
  lang        TEXT NOT NULL               -- nl | en | fr
);
CREATE INDEX IF NOT EXISTS installs_last_seen ON installs(last_seen);

-- Daily activity: at most one row per install per UTC day (for 1d/7d/28d actives).
CREATE TABLE IF NOT EXISTS daily (
  day      TEXT NOT NULL,                 -- YYYY-MM-DD (UTC)
  id       TEXT NOT NULL,
  version  TEXT NOT NULL,
  browser  TEXT NOT NULL,
  lang     TEXT NOT NULL,
  PRIMARY KEY (day, id)
);

-- In-extension feedback. `contact` is optional and never leaves D1 (not in the GitHub issue).
CREATE TABLE IF NOT EXISTS feedback (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  created       INTEGER NOT NULL,         -- ms epoch
  install_id    TEXT,                     -- null when telemetry is off
  kind          TEXT NOT NULL,            -- idea | bug | other
  text          TEXT NOT NULL,
  contact       TEXT,
  version       TEXT,
  browser       TEXT,
  lang          TEXT,
  page          TEXT,                     -- route name only (e.g. 'deadlines')
  status        TEXT NOT NULL DEFAULT 'new', -- new | issued | triaged | closed | spam
  github_issue  INTEGER                   -- issue number when one was created
);
CREATE INDEX IF NOT EXISTS feedback_created ON feedback(created);

-- Fixed-window counters for rate limiting (key contains a hashed IP or an install id, never a raw IP).
CREATE TABLE IF NOT EXISTS ratelimit (
  key     TEXT NOT NULL,
  window  INTEGER NOT NULL,               -- window start, seconds since epoch
  count   INTEGER NOT NULL,
  PRIMARY KEY (key, window)
);

-- Optional runtime config (overrides the LATEST_* vars without a redeploy):
--   npx wrangler d1 execute toledo-plus --remote --command "INSERT OR REPLACE INTO config VALUES ('latest_version','1.2.0')"
CREATE TABLE IF NOT EXISTS config (
  key    TEXT PRIMARY KEY,                -- latest_version | latest_url | latest_notes
  value  TEXT NOT NULL
);
